insert into public.srd_equipment (id,nome,tipo,preco,custo_po,descricao,srd_source_url,categoria,detalhes) values
('srd35_magic_candle_of_truth','Candle of truth','magic_item',2500,2500,'This white tallow candle, when burned, calls into place a zone of truth spell (Will DC 13 negates) in a 5-foot radius centered on the candle. The zone lasts for 1 hour, as the candle burns. If the candle is snuffed before that time, the effect is canceled and the candle ruined.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"2,500 gp","roll_result":"44","raw_table_row":["44","Candle of truth","2,500 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_cloak_of_elvenkind','Cloak of elvenkind','magic_item',2500,2500,'This cloak of neutral gray cloth is indistinguishable from an ordinary cloak of the same color. However, when worn with the hood drawn up around the head, it gives the wearer a +5 competence bonus on Hide checks.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"2,500 gp","roll_result":"45","raw_table_row":["45","Cloak of elvenkind","2,500 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_eyes_of_the_eagle','Eyes of the eagle','magic_item',2500,2500,'These items are made of special crystal and fit over the eyes of the wearer. These lenses grant a +5 competence bonus on Spot checks. Wearing only one of the pair causes a character to become dizzy and, in effect, stunned for 1 round. Thereafter, the wearer can use the single lens without being stunned so long as she covers her other eye. Of course, she can remove the single lens and see normally at any time, or wear both lenses to end or avoid the dizziness.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"2,500 gp","roll_result":"46","raw_table_row":["46","Eyes of the eagle","2,500 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_scarab_golembane','Scarab, golembane','magic_item',2500,2500,'This beetle-shaped pin enables its wearer to detect any golem within 60 feet, although he must concentrate (a standard action) in order for the detection to take place. A scarab enables its possessor to combat golems with weapons, unarmed attacks, or natural weapons as if those golems had no damage reduction.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"2,500 gp","roll_result":"47","raw_table_row":["47","Scarab, golembane","2,500 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_necklace_of_fireballs_type_ii','Necklace of fireballs type II','magic_item',2700,2700,'Listed in Table: Minor Wondrous Items; market price 2,700 gp. The specific item entry is not individually written out in this SRD table.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"2,700 gp","roll_result":"48","raw_table_row":["48","Necklace of fireballs type II","2,700 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":false}'::jsonb),
('srd35_magic_stone_of_alarm','Stone of alarm','magic_item',2700,2700,'This stone cube, when given the command word, affixes itself to any object. If that object is touched thereafter by anyone who does not first speak that same command word, the stone emits a piercing screech for 1 hour that can be heard up to a quarter-mile away (assuming no intervening barriers).','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"2,700 gp","roll_result":"49","raw_table_row":["49","Stone of alarm","2,700 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_bag_of_tricks_rust','Bag of tricks, rust','magic_item',3000,3000,'Listed in Table: Minor Wondrous Items; market price 3,000 gp. The specific item entry is not individually written out in this SRD table.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,000 gp","roll_result":"50","raw_table_row":["50","Bag of tricks, rust","3,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":false}'::jsonb),
('srd35_magic_bead_of_force','Bead of force','magic_item',3000,3000,'This small black sphere appears to be a lusterless pearl. You can throw it up to 60 feet with no range penalties. Upon sharp impact, the bead explodes, sending forth a burst that deals 5d6 points of force damage to all creatures within a 10-foot radius.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,000 gp","roll_result":"51","raw_table_row":["51","Bead of force","3,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_chime_of_opening','Chime of opening','magic_item',3000,3000,'A chime of opening is a hollow mithral tube about 1 foot long. When struck, it sends forth magical vibrations that cause locks, lids, doors, valves, and portals to open. The device functions against normal bars, shackles, chains, bolts, and so on. A chime of opening also automatically dispels a hold portal spell or even an arcane lock cast by a wizard of lower than 15th level.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,000 gp","roll_result":"52","raw_table_row":["52","Chime of opening","3,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_horseshoes_of_speed','Horseshoes of speed','magic_item',3000,3000,'These iron shoes come in sets of four like ordinary horseshoes. When affixed to an animal’s hooves, they increase the animal’s base land speed by 30 feet; this counts as an enhancement bonus. As with other effects that increase speed, jumping distances increase proportionally. All four shoes must be worn by the same animal for the magic to be effective.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,000 gp","roll_result":"53","raw_table_row":["53","Horseshoes of speed","3,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_rope_of_climbing','Rope of climbing','magic_item',3000,3000,'A 60-foot-long rope of climbing is no thicker than a wand, but it is strong enough to support 3,000 pounds. Upon command, the rope snakes forward, upward, downward, or in any other direction at 10 feet per round, attaching itself securely wherever its owner desires. It can unfasten itself and return in the same manner.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,000 gp","roll_result":"54","raw_table_row":["54","Rope of climbing","3,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_dust_of_disappearance','Dust of disappearance','magic_item',3500,3500,'This dust looks just like dust of appearance and is typically stored in the same manner. A creature or object touched by it becomes invisible (as greater invisibility). Normal vision can’t see dusted creatures or objects, nor can they be detected by magical means, including see invisibility or invisibility purge. Dust of appearance, however, does reveal people and objects made invisible by dust of disappearance. Other factors, such as sound and smell, also allow possible detection.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,500 gp","roll_result":"55","raw_table_row":["55","Dust of disappearance","3,500 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_lens_of_detection','Lens of detection','magic_item',3500,3500,'This circular prism enables its user to detect minute details, granting a +5 bonus on Search checks.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,500 gp","roll_result":"56","raw_table_row":["56","Lens of detection","3,500 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_vestment_druid_s','Vestment, druid’s','magic_item',3750,3750,'This light garment is worn over normal clothing or armor. Most such vestments are green, embroidered with plant or animal motifs. When this item is worn by a character with the wild shape ability, the character can use that ability one additional time each day.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,750 gp","roll_result":"57","raw_table_row":["57","Vestment, druid’s","3,750 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_figurine_of_wondrous_power_silver_raven','Figurine of wondrous power, silver raven','magic_item',3800,3800,'Listed in Table: Minor Wondrous Items; market price 3,800 gp. The specific item entry is not individually written out in this SRD table.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Minor Wondrous Items","market_price":"3,800 gp","roll_result":"58","raw_table_row":["58","Figurine of wondrous power, silver raven","3,800 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":false}'::jsonb),
